#define CPPUNIV_SIZE_SEARCH_DIAGNOSTICS
#include "cppunivariate/distributions/zmbinom/mle.hpp"
#include "cppunivariate/distributions/zib/mle.hpp"
#include "cppunivariate/distributions/zib/dpqr.hpp"
#include "cppunivariate/distributions/tbinom/mle.hpp"
#include <iostream>
#include <iomanip>
int main(){std::cout<<std::setprecision(17);std::vector<int>x{1,2,2,3,3,3,4,4,5,5},z=x;z.insert(z.end(),5,0);auto a=cppunivariate::ztbinom_mle({x.data(),x.size()});auto b=cppunivariate::zib_mle({z.data(),z.size()});auto c=cppunivariate::zib_mle({z.data(),z.size()},1e-10,200,NAN,NAN,.2);auto d=cppunivariate::tbinom_design_mle({x.data(),x.size()},0,10,NAN);auto e=cppunivariate::tbinom_design_mle({x.data(),x.size()},0,INFINITY,NAN);std::cout<<int(a.status)<<" "<<a.size<<" "<<a.logLik<<"\n"<<int(b.status)<<" "<<b.size<<" "<<b.logLik<<"\n"<<int(c.status)<<" "<<c.size<<" "<<c.logLik<<"\n"<<int(d.status)<<" "<<d.size<<" "<<d.logLik<<"\n"<<int(e.status)<<" "<<e.size<<" "<<e.logLik<<"\n";std::vector<int> hard(101,100);hard[0]=0;auto h=cppunivariate::tbinom_design_mle({hard.data(),hard.size()},-1,2000,NAN);std::cout<<"hard "<<int(h.status)<<" "<<h.size<<" "<<h.logLik<<std::endl;std::cout<<"hard cutoff "<<cppunivariate::tbinom_detail::size_search_diagnostic.cutoff<<" cells "<<cppunivariate::tbinom_detail::size_search_diagnostic.work<<" certified "<<cppunivariate::tbinom_detail::size_search_diagnostic.certified<<std::endl;std::vector<int> hx{0,1,2,3,4};auto hf=cppunivariate::zib_mle({hx.data(),hx.size()},1e-10,200,1e100,NAN,.2);auto hz=cppunivariate::zip_mle({hx.data(),hx.size()},NAN,.2);double bad=10/4.8,badll=0;for(int v:hx)badll+=cppunivariate::distributions::dzib(v,1e100,bad/1e100,.2,true);std::cout<<"held huge "<<int(hf.status)<<" lambda "<<hf.prob*1e100<<" ll "<<hf.logLik<<" zip "<<hz.lambda<<" zipll "<<hz.logLik<<" old-rounded-score lambda "<<bad<<" ll "<<badll<<std::endl;}
